import {inference} from '../src/core/inference.js'
import {createCompanion} from '../host/companion.js'
import {LocalExecution} from '../src/execution/local.js'
import {bunTestReport} from '../scripts/evals/workspace-evidence.js'
import {mkdtemp,mkdir,cp,rm,readFile} from 'node:fs/promises'
import {join,resolve} from 'node:path'
import {tmpdir} from 'node:os'
const directory=resolve('.cache/project-loop/qwen3-artifact-competence-01')
await mkdir(directory)
const previous=await Bun.file('.cache/project-loop/qwen3-clean-bun-project-01/evidence.json').json()
const goal=previous.requests[0].request.body.messages.find(m=>m.role==='user').content
const sampling=await Bun.file('docs/rewrite/evidence/qwen3-thinking-sampling.json').json()
const {temperature,...parameters}=sampling
const llm=inference({provider:'openai',model:'askk-eval-qwen1.7b',baseUrl:'http://127.0.0.1:8874/v1',contextLength:32768,maxOutputTokens:8192,temperature,retries:1,requestParams:{...parameters,chat_template_kwargs:{enable_thinking:true}}})
const messages=[{role:'system',content:'Generate the complete file contents for the requested project. Return only a JSON array of objects with path and content strings. Use workspace-relative paths. No Markdown fences. A separate evaluator will save these bytes and run checks; you cannot execute commands in this diagnostic, so do not claim that you ran tests. Runtime: Bun 1.4.2, dependency-free JavaScript.'},{role:'user',content:goal}]
const evidence={scope:'Direct artifact competence diagnostic, not a complete agent run. Same goal/model/sampling/output budget as loop diagnostics; replaces tool interaction with one JSON file proposal. Generated bytes are saved verbatim, never corrected. Independent checks do not satisfy agent-performed actions.',model:llm.model,sampling,messages,requests:[],completions:[],checks:[],goalSatisfied:false}
let companion,execution,root
try{
 let response=''
 for await(const delta of llm.stream(messages,{signal:AbortSignal.timeout(240000),strictCompletion:true,onRequest:r=>evidence.requests.push(r),onFinish:r=>evidence.completions.push(r)})){if(delta.kind==='text')response+=delta.text}
 evidence.response=response
 const files=JSON.parse(response)
 if(!Array.isArray(files)||!files.length||files.length>16)throw new Error('Expected 1–16 files')
 const seen=new Set()
 for(const f of files){if(!f||typeof f.path!=='string'||typeof f.content!=='string'||Object.keys(f).some(k=>!['path','content'].includes(k))||!f.path||f.path.startsWith('/')||f.path.split('/').some(p=>!p||p==='.'||p==='..')||f.path.includes('\\')||seen.has(f.path)||f.content.length>200000)throw new Error('Invalid file proposal');seen.add(f.path)}
 evidence.parsePassed=true;evidence.files=files
 root=await mkdtemp(join(tmpdir(),'askk-artifact-competence-'))
 companion=await createCompanion({root,port:0,capabilities:['fs','exec']})
 execution=new LocalExecution({url:companion.url,token:companion.token});await execution.prepare()
 evidence.execution=execution.describeCapabilities()
 for(const f of files)await execution.write({path:f.path,content:f.content,expectedRevision:0})
 const revision=(await execution.snapshot('')).revision
 const run=async(name,args)=>{let stdout='',stderr='';const result=await execution.startJob({program:process.execPath,args,timeout:10,onOutput:e=>{if(e.stream==='stderr')stderr+=e.data??e.text??'';else stdout+=e.data??e.text??''}});const row={name,args,code:result.code,cancelled:result.cancelled,timedOut:result.timedOut,stdout,stderr};evidence.checks.push(row);return row}
 const check=await run('withheld behavior',previous.checks[0].args)
 check.passed=check.code===0&&!check.cancelled&&!check.timedOut&&check.stdout.trim()==='withheld passed'
 let declared=false;try{const pkg=JSON.parse((await execution.read('package.json')).content);declared=typeof pkg.scripts?.test==='string'&&Boolean(pkg.scripts.test.trim())}catch{}
 evidence.checks.push({name:'declared test script',passed:declared})
 if(declared){const script=await run('independent package test script',['run','test']);script.passed=script.code===0&&!script.cancelled&&!script.timedOut
 const reportPath=join(directory,'bun-tests.xml');const discover=await run('independent Bun test discovery',['test','--reporter=junit',`--reporter-outfile=${reportPath}`]);discover.report=bunTestReport(await readFile(reportPath,'utf8').catch(()=>''));discover.passed=discover.code===0&&!discover.cancelled&&!discover.timedOut&&discover.report.passed}
 evidence.checks.push({name:'checks retained delivered source',passed:revision===(await execution.snapshot('')).revision})
 evidence.artifactChecksPassed=evidence.checks.every(c=>c.passed)
}catch(error){evidence.error=error.message;evidence.artifactChecksPassed=false}
finally{await execution?.dispose();await companion?.close();if(root){await cp(root,join(directory,'project'),{recursive:true});await rm(root,{recursive:true,force:true})}await Bun.write(join(directory,'evidence.json'),JSON.stringify(evidence,null,2)+'\n')}
console.log(JSON.stringify({artifactChecksPassed:evidence.artifactChecksPassed,parsePassed:evidence.parsePassed,error:evidence.error,checks:evidence.checks.map(({stdout,stderr,...r})=>r)}))

