export function total(values) {
  if (!Array.isArray(values)) {
    throw new Error('Expected an array');
  }
  for (const value of values) {
    if (typeof value !== 'number') {
      throw new Error('All elements must be numbers');
    }
    if (isNaN(value) || value === Infinity || value === -Infinity) {
      throw new Error('All elements must be finite numbers');
    }
  }
  return values.reduce((sum, num) => sum + num, 0);
}

test('sum empty array', () => {
  expect(total([])).toBe(0);
});

test('sum with numbers', () => {
  expect(total([1, 2, 3])).toBe(6);
});

test('sum with non-numeric', () => {
  expect(() => total(['a', 2, 3])).toThrow();
});

test('sum with non-finite', () => {
  expect(() => total([1, Infinity, 3])).toThrow();
});

test('sum with NaN', () => {
  expect(() => total([1, NaN, 3])).toThrow();
});

test('sum with negative numbers', () => {
  expect(total([-1, -2, -3])).toBe(-6);
});

test('sum with zero', () => {
  expect(total([0])).toBe(0);
});

test('sum with mixed numbers and non-numeric', () => {
  expect(() => total([1, 'a', 3])).toThrow();
});

import { test, expect } from 'bun:test'
import { total } from './total.js'

test('total of empty array', () => {
  expect(total([])).toBe(0)
})

test('total of array with numbers', () => {
  expect(total([1, 2, 3])).toBe(6)
})

test('total of array with non-numeric values', () => {
  expect(total([1, 'two', 3])).toThrowError()
})

test('total of array with non-finite values', () => {
  expect(total([1, NaN, 3])).toThrowError()
})
